CREATE TABLE IF NOT EXISTS "MobileDeviceTokens"
(
    "Id"          integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId"      character varying(450)      NOT NULL,
    "Token"       character varying(450)      NOT NULL,
    "Platform"    character varying(20),
    "LastSeenAt"  timestamp without time zone NOT NULL,
    "IsActive"    boolean                     NOT NULL DEFAULT true,
    "CreatedBy"   text,
    "CreatedAt"   timestamp without time zone NOT NULL,
    "EditedBy"    text,
    "EditedAt"    timestamp without time zone NOT NULL,
    "MACAddress"  text,
    CONSTRAINT "PK_MobileDeviceTokens" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_MobileDeviceTokens_Token"
    ON "MobileDeviceTokens" ("Token");

CREATE INDEX IF NOT EXISTS "IX_MobileDeviceTokens_UserId_IsActive"
    ON "MobileDeviceTokens" ("UserId", "IsActive");
